t.script:
(function () {
    function filterStudentServices() {
        const formPortal = document.querySelector(
            '.student-form-portal'
        );

        if (!formPortal) {
            return;
        }

        const selectedCategory = new URLSearchParams(
            window.location.search
        ).get('category');

        const validCategories = [
            'documents',
            'student',
            'academic',
            'tuition',
            'graduation',
            'support'
        ];

        const isValidCategory =
            validCategories.includes(selectedCategory);

        const groups = formPortal.querySelectorAll(
            '.request-type-group'
        );

        let firstVisibleRadio = null;

        groups.forEach(function (group) {
            const category = group.dataset.serviceCategory;

            const isVisible =
                !isValidCategory ||
                category === selectedCategory;

            group.hidden = !isVisible;

            if (isVisible && isValidCategory) {
                group.open = true;
            }

            if (isVisible && !firstVisibleRadio) {
                firstVisibleRadio = group.querySelector(
                    'input[name="request_type"]'
                );
            }
        });

        const allRadios = formPortal.querySelectorAll(
            'input[name="request_type"]'
        );

        allRadios.forEach(function (radio) {
            radio.required = false;
        });

        if (firstVisibleRadio) {
            firstVisibleRadio.required = true;
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener(
            'DOMContentLoaded',
            filterStudentServices
        );
    } else {
        filterStudentServices();
    }
})();
